insert into public.sections (key, draft, published, position) values ('hero', '{"visible":true,"label":"Projetos e produtos de iluminação","title":"Sua casa,","title2":"sua luz.","text":"Projeto e curadoria de iluminação, do seu jeito.","cta":"Saiba mais","image":"/img/hero.jpg","items":[]}'::jsonb, '{"visible":true,"label":"Projetos e produtos de iluminação","title":"Sua casa,","title2":"sua luz.","text":"Projeto e curadoria de iluminação, do seu jeito.","cta":"Saiba mais","image":"/img/hero.jpg","items":[]}'::jsonb, 0) on conflict (key) do update set draft = excluded.draft, published = excluded.published, position = excluded.position;
insert into public.sections (key, draft, published, position) values ('quem', '{"visible":true,"label":"Quem somos","title":"Na Brasília Iluminação, a luz é sentida antes de ser vista.","title2":"","text":"Em uma só marca vivem duas paixões: um escritório de projetos luminotécnicos e uma curadoria dos melhores produtos de iluminação.","cta":"","image":"","items":[{"title":"17|anos","text":"Especialistas em luz — Uma arquiteta e designer de interiores, pós-graduada em cálculo luminotécnico, desenhando luz desde a faculdade."},{"title":"1|só lugar","text":"Projeto e produto juntos — Do briefing à última lâmpada acesa, sem ruído entre quem projeta e quem fornece."},{"title":"27|UFs","text":"Curadoria que viaja — Os melhores produtos do mercado, escolhidos a dedo e entregues para todo o Brasil."}]}'::jsonb, '{"visible":true,"label":"Quem somos","title":"Na Brasília Iluminação, a luz é sentida antes de ser vista.","title2":"","text":"Em uma só marca vivem duas paixões: um escritório de projetos luminotécnicos e uma curadoria dos melhores produtos de iluminação.","cta":"","image":"","items":[{"title":"17|anos","text":"Especialistas em luz — Uma arquiteta e designer de interiores, pós-graduada em cálculo luminotécnico, desenhando luz desde a faculdade."},{"title":"1|só lugar","text":"Projeto e produto juntos — Do briefing à última lâmpada acesa, sem ruído entre quem projeta e quem fornece."},{"title":"27|UFs","text":"Curadoria que viaja — Os melhores produtos do mercado, escolhidos a dedo e entregues para todo o Brasil."}]}'::jsonb, 1) on conflict (key) do update set draft = excluded.draft, published = excluded.published, position = excluded.position;
insert into public.sections (key, draft, published, position) values ('formas', '{"visible":true,"label":"Formas de trabalhar","title":"Você escolhe como quer a nossa presença.","title2":"","text":"Do projeto completo à compra com consultoria: quatro jeitos de ter a luz certa em casa.","cta":"","image":"","items":[{"title":"Projeto completo","text":"Projeto luminotécnico, curadoria e venda dos produtos, com acompanhamento na obra."},{"title":"Somente o projeto","text":"O projeto e a especificação. Você compra onde preferir."},{"title":"Já tem projeto? Fornecemos os produtos","text":"Traga o projeto do seu arquiteto, e nós cuidamos da curadoria."},{"title":"Compre online com nossos consultores","text":"Já sabe o que procura? Compre online, com a nossa curadoria."}]}'::jsonb, '{"visible":true,"label":"Formas de trabalhar","title":"Você escolhe como quer a nossa presença.","title2":"","text":"Do projeto completo à compra com consultoria: quatro jeitos de ter a luz certa em casa.","cta":"","image":"","items":[{"title":"Projeto completo","text":"Projeto luminotécnico, curadoria e venda dos produtos, com acompanhamento na obra."},{"title":"Somente o projeto","text":"O projeto e a especificação. Você compra onde preferir."},{"title":"Já tem projeto? Fornecemos os produtos","text":"Traga o projeto do seu arquiteto, e nós cuidamos da curadoria."},{"title":"Compre online com nossos consultores","text":"Já sabe o que procura? Compre online, com a nossa curadoria."}]}'::jsonb, 2) on conflict (key) do update set draft = excluded.draft, published = excluded.published, position = excluded.position;
insert into public.sections (key, draft, published, position) values ('camila', '{"visible":true,"label":"A assinatura","title":"Camila de Lelis","title2":"","text":"Há quase 17 anos, Camila desenha a luz de casas, salas e jardins. Arquiteta e designer de interiores, com pós-graduação em cálculo luminotécnico, ela transforma cada ambiente em experiência.\n\nTodo projeto nasce da rotina e do gosto de quem vai viver nele. É assim que a luz deixa de ser um detalhe e passa a ser uma assinatura.","cta":"","image":"/img/camila.jpg","items":[{"title":"Arquiteta","text":""},{"title":"Designer de interiores","text":""},{"title":"Pós em cálculo luminotécnico","text":""}]}'::jsonb, '{"visible":true,"label":"A assinatura","title":"Camila de Lelis","title2":"","text":"Há quase 17 anos, Camila desenha a luz de casas, salas e jardins. Arquiteta e designer de interiores, com pós-graduação em cálculo luminotécnico, ela transforma cada ambiente em experiência.\n\nTodo projeto nasce da rotina e do gosto de quem vai viver nele. É assim que a luz deixa de ser um detalhe e passa a ser uma assinatura.","cta":"","image":"/img/camila.jpg","items":[{"title":"Arquiteta","text":""},{"title":"Designer de interiores","text":""},{"title":"Pós em cálculo luminotécnico","text":""}]}'::jsonb, 3) on conflict (key) do update set draft = excluded.draft, published = excluded.published, position = excluded.position;
insert into public.sections (key, draft, published, position) values ('lumi', '{"visible":true,"label":"O projeto luminotécnico","title":"O início de uma casa bem iluminada.","title2":"","text":"Marcar pontos de luz na planta é só o começo: o projeto pensa a luz em cenas e entrega o executivo completo, para a obra sair certa e o orçamento não fugir.","cta":"Faça seu orçamento","image":"","items":[{"title":"Briefing e leitura da rotina","text":"Entender o gosto e o dia a dia de quem vai viver ali, antes da luz."},{"title":"Cenas de luz","text":"O comando de cada cena, pensando no seu dia, principalmente à noite."},{"title":"Projeto executivo","text":"Três plantas que orientam toda a execução do luminotécnico na obra."},{"title":"As peças certas","text":"A especificação e a lista pronta para a compra, com pós-venda até a última lâmpada."}]}'::jsonb, '{"visible":true,"label":"O projeto luminotécnico","title":"O início de uma casa bem iluminada.","title2":"","text":"Marcar pontos de luz na planta é só o começo: o projeto pensa a luz em cenas e entrega o executivo completo, para a obra sair certa e o orçamento não fugir.","cta":"Faça seu orçamento","image":"","items":[{"title":"Briefing e leitura da rotina","text":"Entender o gosto e o dia a dia de quem vai viver ali, antes da luz."},{"title":"Cenas de luz","text":"O comando de cada cena, pensando no seu dia, principalmente à noite."},{"title":"Projeto executivo","text":"Três plantas que orientam toda a execução do luminotécnico na obra."},{"title":"As peças certas","text":"A especificação e a lista pronta para a compra, com pós-venda até a última lâmpada."}]}'::jsonb, 4) on conflict (key) do update set draft = excluded.draft, published = excluded.published, position = excluded.position;
insert into public.sections (key, draft, published, position) values ('loja', '{"visible":true,"label":"A curadoria","title":"As peças certas, escolhidas por quem projeta.","title2":"","text":"Luminárias, pendentes e peças decorativas selecionadas com o mesmo olhar dos nossos projetos. Compre na loja online ou com a ajuda de uma consultora.","cta":"Visite a loja","image":"","items":[]}'::jsonb, '{"visible":true,"label":"A curadoria","title":"As peças certas, escolhidas por quem projeta.","title2":"","text":"Luminárias, pendentes e peças decorativas selecionadas com o mesmo olhar dos nossos projetos. Compre na loja online ou com a ajuda de uma consultora.","cta":"Visite a loja","image":"","items":[]}'::jsonb, 5) on conflict (key) do update set draft = excluded.draft, published = excluded.published, position = excluded.position;
insert into public.sections (key, draft, published, position) values ('oferta', '{"visible":true,"label":"Também oferecemos","title":"Mais caminhos para a luz certa.","title2":"","text":"","cta":"","image":"","items":[{"title":"Orientação para compra","text":"Para quem quer só uma ajuda para escolher as peças certas, sem projeto completo."},{"title":"Luz para paisagismo","text":"O jardim bonito de dia e à noite, com a iluminação certa."},{"title":"Projetos comerciais","text":"Iluminação que valoriza lojas, escritórios e espaços de atendimento."}]}'::jsonb, '{"visible":true,"label":"Também oferecemos","title":"Mais caminhos para a luz certa.","title2":"","text":"","cta":"","image":"","items":[{"title":"Orientação para compra","text":"Para quem quer só uma ajuda para escolher as peças certas, sem projeto completo."},{"title":"Luz para paisagismo","text":"O jardim bonito de dia e à noite, com a iluminação certa."},{"title":"Projetos comerciais","text":"Iluminação que valoriza lojas, escritórios e espaços de atendimento."}]}'::jsonb, 6) on conflict (key) do update set draft = excluded.draft, published = excluded.published, position = excluded.position;
