insert into public.sections (key, draft, published, position) values ('contato', '{"visible":true,"label":"Entre em contato","title":"Vamos dar luz ao seu","title2":"projeto?","text":"Preencha e receba um retorno rápido. Diga se quer o projeto, só os produtos, ou os dois.","cta":"Enviar","image":"","items":[]}'::jsonb, '{"visible":true,"label":"Entre em contato","title":"Vamos dar luz ao seu","title2":"projeto?","text":"Preencha e receba um retorno rápido. Diga se quer o projeto, só os produtos, ou os dois.","cta":"Enviar","image":"","items":[]}'::jsonb, 9) on conflict (key) do update set draft = excluded.draft, published = excluded.published, position = excluded.position;
insert into public.settings (id, data) values (1, '{"hero":"cobogo","whatsapp":"(61) 98358-3129","email":"contato@brasiliailuminacao.com.br","instagram":"@brasilia_iluminacao","shopUrl":"https://shop.brasiliailuminacao.com.br/","seoTitle":"Brasília Iluminação — Projetos e produtos de iluminação","seoDescription":"Projeto luminotécnico e curadoria de iluminação em Brasília, com entrega para todo o Brasil."}'::jsonb) on conflict (id) do update set data = excluded.data;
