insert into public.testimonials (quote, author, location, position, visible) values ('Além de técnica, muito humana. Me senti ouvida, cuidada e compreendida.', 'Tatiana Murta', 'Lago Norte / DF', 0, true);
insert into public.testimonials (quote, author, location, position, visible) values ('Me senti acolhido em todo o processo e indicaria com certeza.', 'Vitor', 'Jardim Botânico / DF', 1, true);
insert into public.testimonials (quote, author, location, position, visible) values ('Materiais bem especificados e soluções para melhorar o custo-benefício. Pós-venda dentro do esperado.', 'Hugo Affonso', 'Sudoeste / DF', 2, true);
insert into public.faqs (question, answer, position, visible) values ('Preciso contratar o projeto para comprar os produtos?', 'Não. Você pode comprar apenas os produtos, com o seu projeto ou com um projeto desenvolvido por nós. A curadoria é a mesma.', 0, true);
insert into public.faqs (question, answer, position, visible) values ('Posso trazer o meu próprio projeto?', 'Sim. Se você ou o seu arquiteto já têm o projeto, cuidamos da curadoria e da compra das peças certas.', 1, true);
insert into public.faqs (question, answer, position, visible) values ('Vale a pena o projeto luminotécnico?', 'Muito. É o que garante a luz certa desde o começo, evita desperdício e traz emoção a cada ambiente.', 2, true);
insert into public.faqs (question, answer, position, visible) values ('Vocês atendem fora de Brasília?', 'Sim. Somos de Brasília e entregamos para todo o Brasil, com atendimento online.', 3, true);
